import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my_last, opp_last = history[-1]

    # Defect against a confirmed defector, but avoid being exploited early.
    if n >= 2:
        opp_defections = sum(1 for _, o in history if o == 'D')
        if opp_defections >= 3 and opp_defections >= n // 2:
            return 'D'

    # Tit-for-two-tats: cooperate unless opponent defected on the last two rounds.
    if n >= 2:
        if history[-1][1] == 'D' and history[-2][1] == 'D':
            return 'D'

    # Endgame: defect in the final few rounds to secure payoff.
    remaining = 100 - n
    if remaining <= 2:
        return 'D'

    # Occasional probing / retaliation against persistent defection.
    if opp_last == 'D' and my_last == 'D':
        if rng.random() < 0.7:
            return 'D'

    return 'C'

